import{z as i,x as s,o as B,c as p,q as n,j as r,D as e,d as l,s as t,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"可比与乘数","description":"","frontmatter":{"title":"可比与乘数","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/multiples-valuation.md","filePath":"econ/multiples-valuation.md","lastUpdated":1791413859000}'),D={name:"econ/multiples-valuation.md"};function d(C,a,F,m,u,T){const A=s("Mermaid");return B(),p("div",null,[a[2]||(a[2]=n('<h1 id="可比与乘数" tabindex="-1">可比与乘数 <a class="header-anchor" href="#可比与乘数" aria-label="Permalink to &quot;可比与乘数&quot;">​</a></h1><div class="epigraph"><p>乘数是把市场对一组相似资产的定价，压缩成价格对盈利、账面或收入的比率；它不是独立于折现的第二种经济学，而是同一价值的简写，误差来自「相似」失败。</p><footer>—— 据 Kaplan and Ruback, The Valuation of Cash Flow Forecasts: An Empirical Analysis, Journal of Finance 1995；Brealey, Myers and Allen 整理</footer></div><p><a href="/econ/dcf-terminal-value">上一课</a>把 DCF 终值写成 \\(g\\) 与 ROIC 的假设，并点名退出倍数是终值的另一写法。本课缺口是把倍数当成完整估值方法：何时 EV/EBIT、P/E、收入倍数可替代显式 DCF，何时只是对照。不重推 Gordon 公式，不把限价簿上的相对价值交易当成公司估值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DCF 的分子与 \\(r\\) 都要预测；市场已经对上市可比给了价格。若可比与目标在增长、ROIC、风险、杠杆上接近，价格/基本面的中位数是目标价值的估计。Kaplan 与 Ruback（1995）对高杠杆交易的现金流预测做折现，发现 DCF 与交易倍数都能接近事后市值，不是「倍数更科学」或「DCF 更科学」。缺口是：倍数把终值假设压缩进一个比率，省掉 \\(g\\) 与 \\(r\\) 的争吵，同时把不可比藏进同一个中位数。</p><p>接受规则仍是 NPV：倍数给出的是相对定价，不自动等于项目对股东的增量价值——尤其当项目改变公司风险或当控制权溢价存在时。</p><p><span class="marginnote">数字实例：可比中位数 EV/EBITDA 为 8 倍，目标公司 EBITDA 5 亿，企业价值就是 40 亿；减净债 10 亿，股权值 30 亿。若错拿同行高杠杆公司的 P/E 来套，等于把对方的负债结构也塞进了你的定价。</span></p><p><span class="marginnote">企业价值倍数（EV/EBIT、EV/EBITDA）对应全资本，与 WACC/APV 对齐。股权倍数（P/E）掺进杠杆与税，跨公司比较先要杠杆相近，否则是把融资切片写进经营比较。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先选可比：同行、纯业务、相近增长与周期。再选口径：前瞻对历史、剔除一次性、EBITDA 是否加回真实的现金成本。用中位数或回归（把倍数对增长、利润率回归）比用最高的一个「对标」。目标杠杆与可比不同，用 EV 倍数再减净债，不要直接套一个高杠杆公司的 P/E。</p><p>收入倍数出现在亏损或早期：它假设未来利润率收敛到可比。这是终值假设的另一种藏法，往往比 DCF 更乐观，因为利润率尚未被显式期约束。</p><p><span class="marginnote">EBITDA 读作「息税折旧摊销前利润」。术语翻译：它就是「先不问钱是谁借的、设备有多旧，只看生意本身赚不赚现金」的口径——所以跨公司比它，比的是经营，掺不进融资与会计折旧；一旦某家把租赁藏进费用，口径就破了。</span></p>',12)),(B(),r(o,null,{default:e(()=>[t(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PEER%5B%22%E5%8F%AF%E6%AF%94%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20MULT%5B%22%E5%80%8D%E6%95%B0%22%5D%0A%20%20FUND%5B%22%E7%9B%88%E5%88%A9%20%2F%20%E8%B4%A6%E9%9D%A2%20%2F%20%E6%94%B6%E5%85%A5%22%5D%20--%3E%20MULT%0A%20%20MULT%20--%3E%20REL%5B%22%E7%9B%B8%E5%AF%B9%E4%BB%B7%E5%80%BC%22%5D%0A%20%20DCF%5B%22DCF%22%5D%20--%3E%20CHK%5B%22%E5%AF%B9%E7%85%A7%22%5D%0A%20%20REL%20--%3E%20CHK%0A%20%20DIFF%5B%22%E5%A2%9E%E9%95%BF%E9%A3%8E%E9%99%A9%E6%9D%A0%E6%9D%86%E4%B8%8D%E5%90%8C%22%5D%20--%3E%20BIAS%5B%22%E4%B8%AD%E4%BD%8D%E6%95%B0%E5%81%8F%E5%B7%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"控制权：交易倍数含控制溢价，交易价格对少数股权市值倍数会偏高。并购课再写协同与支付；本课只标：资本预算用交易倍数去估一个少数股权项目，口径错了。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是一价定律的粗糙版本：相似资产应有相似的价格/基本面。MM 说切片不改变总 EV（无摩擦时），所以经营相似的企业 EV/NOPAT 应接近，P/E 可以因杠杆不同而不同。倍数失败，是因为「相似」在增长期权、会计、周期位置上失败——同一行业的会计折旧与租赁资本化可以让 EBITDA 不可比。",-1)),a[6]||(a[6]=E("p",null,"与 DCF 的对偶：Gordon 下 \\(P_0=\\mathrm{FCFF}_1/(r-g)\\)，所以 EV/FCFF \\(=1/(r-g)\\)。倍数高，要么 \\(r\\) 低，要么 \\(g\\) 高，要么市场错了。资本预算若只用行业高倍数来给内部项目定价，等于导入了市场对同行增长的假设，却不检查本项目是否有同样的再投资与壁垒。",-1)),(B(),r(o,null,{default:e(()=>[t(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20MULT%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E5%81%8F%E9%AB%98%E7%9A%84%20EV%2FEBITDA%20%E8%AF%BB%E6%95%B0%22%5D%20--%3E%20R%5B%22%E5%88%86%E6%AF%8D%E4%B9%8B%E4%B8%80%3A%20%E8%B4%B4%E7%8E%B0%E7%8E%87%20r%20%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20MULT%20--%3E%20G%5B%22%E5%88%86%E6%AF%8D%E4%B9%8B%E4%BA%8C%3A%20%E5%A2%9E%E9%95%BF%E9%A2%84%E6%9C%9F%20g%20%E8%A2%AB%E6%8A%AC%E9%AB%98%22%5D%0A%20%20MULT%20--%3E%20ACC%5B%22%E5%8F%A3%E5%BE%84%E5%A4%B1%E7%9C%9F%3A%20%E4%BC%9A%E8%AE%A1%E4%B8%8D%E5%8F%AF%E6%AF%94%22%5D%0A%20%20ACC%20--%3E%20D1%5B%22%E6%8A%98%E6%97%A7%E5%B9%B4%E9%99%90%E4%B8%8D%E5%90%8C%22%5D%0A%20%20ACC%20--%3E%20D2%5B%22%E7%A7%9F%E8%B5%81%E6%9C%AA%E8%B5%84%E6%9C%AC%E5%8C%96%22%5D%0A%20%20R%20--%3E%20J%5B%22%E4%B8%80%E4%BB%B7%E5%AE%9A%E5%BE%8B%3A%20%E7%9B%B8%E4%BC%BC%E4%BC%81%E4%B8%9A%E5%80%8D%E6%95%B0%E5%BA%94%E6%8E%A5%E8%BF%91%22%5D%0A%20%20G%20--%3E%20J%0A%20%20ACC%20--%3E%20B%5B%22%E4%B8%AD%E4%BD%8D%E6%95%B0%E5%A4%B1%E7%9C%9F%2C%20%E7%9B%B8%E4%BC%BC%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：\\(r=10\\%\\)、\\(g=4\\%\\) 时 EV/FCFF \\(=1/(0.10-0.04)\\approx 16.7\\) 倍；市场把 \\(r\\) 抬到 \\(12\\%\\)，同一公式只剩 \\(12.5\\) 倍。倍数的起落大半是分母里这两个参数在动，不必次次归因于「市场疯了」。</span></p><h3 id="不要用倍数绕过增量" tabindex="-1">不要用倍数绕过增量 <a class="header-anchor" href="#不要用倍数绕过增量" aria-label="Permalink to &quot;不要用倍数绕过增量&quot;">​</a></h3><p>项目 NPV 是增量。公司交易倍数给出的是整家企业。把「行业 10 倍 EBITDA」乘在项目 EBITDA 上，忽略项目衰减、协同为负、以及期末资本支出。倍数是对照与终值输入，不能单独替代上一课的增量 FCFF。</p><p><span class="marginnote">会计：EBITDA 加回折旧，但折旧对应的维护性 capex 仍要发生。高 capex 行业的 EV/EBITDA 偏贵看起来便宜。Penman：倍数要与剩余收益、净经营资产放在同一套干净盈余里读。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成投行 pitch 的倍数清单。对象是与 DCF 的信息等价与失败条件。也不要把量化栏的相对价值统计套利搬进来：那是交易协议与因子，不是项目接受。后课 EVA 给出会计上与 DCF 等价的第三条路，仍不是倍数。</p><p>后课默认：倍数是相对定价简写，EV 口径优先；与 DCF 对照，不替代增量 NPV。相似失败时中位数没有经济学。下一课：剩余收益把账面与剩余价值连回同一 \\(V\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>倍数压缩了 \\(r\\) 与 \\(g\\)；可比失败则中位数无意义。</li><li>EV 倍数对齐全资本；P/E 掺进杠杆。交易倍数含控制权。</li><li>Kaplan–Ruback：DCF 与倍数可同样接近市值；资本预算仍以增量 NPV 为准。</li><li>出处：Kaplan and Ruback, <em>JF</em> 1995；Brealey, Myers and Allen。</li></ul>',9))])}const V=i(D,[["render",d]]);export{h as __pageData,V as default};
